from collections import Counter
from pathlib import Path
import re

files = ("discord", "postman", "retroarch", "sqlitebrowser", "telegram", "zoom")
field = re.compile(r'(\w+)=((?:"(?:[^"\\]|\\.)*")|\S+)')
for name in files:
    rows = []
    for line in Path(name).read_text(encoding="utf-8", errors="replace").splitlines():
        values = {key: value.strip('"') for key, value in field.findall(line)}
        if values.get("apparmor") == "ALLOWED" and "denied_mask" in values:
            rows.append(
                (
                    values.get("operation", "?"),
                    values["denied_mask"],
                    values.get("name", "?"),
                    values.get("profile", "?"),
                    values.get("requested_mask", "?"),
                )
            )
    print(f"[{name}] evidence-backed denied-mask records: {len(rows)}")
    for row, count in Counter(rows).most_common():
        operation, denied, object_name, profile, requested = row
        print(
            f"  {count:4} operation={operation} requested={requested} "
            f"denied={denied} profile={profile} name={object_name}"
        )
    print()
